#include <stdio.h>

void reverse_array(int arr[], int size) {
    int start = 0;
    int end = size - 1;
    while (start < end) {
        int tmp = arr[start];
        arr[start] = arr[end];
        arr[end] = tmp;
        start++;
        end--;
    }
}

int main() {
    int nums[] = {1, 2, 3, 4, 5};
    reverse_array(nums, 5);
    printf("First: %d\n", nums[0]);
    return 0;
}

#include <stdio.h>

void bubble_sort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int t = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = t;
            }
        }
    }
}

int main() {
    int a[] = {5, 1, 4, 2, 8};
    bubble_sort(a, 5);
    printf("Sorted first: %d\n", a[0]);
    return 0;
}

#include <stdio.h>

long long power(int base, int exp) {
    long long result = 1;
    long long b = base;
    int e = exp;
    while (e > 0) {
        if (e % 2 == 1) {
            result = result * b;
        }
        b = b * b;
        e = e / 2;
    }
    return result;
}

int main() {
    long long ans = power(2, 10);
    printf("2^10 = %lld\n", ans);
    return 0;
}

