def top_k_elements(items, k):
    counts = {}
    for it in items:
        counts[it] = counts.get(it, 0) + 1
    sorted_items = sorted(counts.items(), key=lambda pair: pair[1], reverse=True)
    return [item for item, _ in sorted_items[:k]]

