import time

def simple_profiler(func):
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        return result, elapsed
    return wrapper

@simple_profiler
def slow_sum(limit):
    return sum(range(limit))

if __name__ == '__main__':
    ans, t = slow_sum(1000)
    print(f'Sum: {ans}, elapsed: {t:.6f}s')

def is_balanced_parentheses(text):
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}
    for char in text:
        if char in pairs.values():
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
    return len(stack) == 0

if __name__ == '__main__':
    print(is_balanced_parentheses('({[]})'))

def memoize(fn):
    cache = {}
    def inner(arg):
        if arg not in cache:
            cache[arg] = fn(arg)
        return cache[arg]
    return inner

@memoize
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

if __name__ == '__main__':
    print(f'Fib 10: {fib(10)}')
